/**
 * Every subdivision boundary as a plain ring, with the country it belongs to.
 *
 * The 3D twin needs rings rather than GeoJSON features and asks on every
 * rebuild; walking 4,500 features each time is the difference between an
 * instant rebuild and a visible stall.
 */
let _rings = null;

export function admin1Rings() {
  if (_rings) return _rings;
  _rings = [];
  for (const f of ADMIN1.features) {
    for (const poly of f.geometry.coordinates) {
      if (poly[0] && poly[0].length >= 4) {
        _rings.push({ ring: poly[0], admin: f.properties.admin,
                      name: f.properties.name });
      }
    }
  }
  return _rings;
}
